import{z as p,x as s,o as n,c,q as i,j as A,D as t,d as E,s as r,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"pin 与 latch","description":"","frontmatter":{"title":"pin 与 latch","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pin-latch.md","filePath":"cs/pin-latch.md","lastUpdated":1791413859000}'),o={name:"cs/pin-latch.md"};function h(d,a,u,D,m,b){const l=s("Mermaid");return n(),c("div",null,[a[2]||(a[2]=i('<h1 id="pin-与-latch" tabindex="-1">pin 与 latch <a class="header-anchor" href="#pin-与-latch" aria-label="Permalink to &quot;pin 与 latch&quot;">​</a></h1><div class="epigraph"><p>pin 计数禁止缓冲池换出正在读的页；latch 是页上的短互斥，保护槽与页头，不是事务锁。</p><footer>—— 据 Gray and Reuter；Mohan 对 latch；Ramakrishnan and Gehrke 对缓冲与并发</footer></div><p><a href="/cs/buffer-pool-lru-k">上一课</a>选出牺牲帧。本课不重写 LRU-K。缺口是并发与寿命：工人 A 正解码页上的槽，替换线程不能把帧交给另一表。pin（钉住）解决寿命；latch（闩锁）解决页内结构的互斥。二者都不是 2PL 的行锁。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>事务锁持有时间跨用户交互，粒度为行或表。页结构（槽数组、空闲空间、LSN）必须在微秒级互斥下改。若用事务锁锁页，粒度太粗、持有太长。latch：读闩/写闩，协议是短临界区，不允许在持 latch 时做 I/O 等待（通常）。pin：<code>pin_count++</code> 直到 unpin，替换跳过 pin&gt;0 的帧。</p><p><span class="marginnote">直觉类比：pin 像把书从架上「借走登记」，管理员（替换线程）不能收走；latch 像你翻书时手按住的那一页——别人等你看完这页再动。两件事互不相干，各管一层。</span></p><p>缺口是<strong>两层并发</strong>：事务隔离一层，页物理完整性一层。混用会把死锁检测搞乱——latch 死锁通常靠固定顺序避免，不走 wait-for 图。</p><p><span class="marginnote">Gray and Reuter 区分 lock 与 latch。ARIES 论文里 latch 保护缓冲页。本课不讲 B+ 上的 crabbing，下一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读页：pin → 取读 latch → 复制或使用指针 → 放 latch → 稍后 unpin（或在使用期间保持 pin）。改页：写 latch 下改，写 WAL，更新 pageLSN，放 latch。顺序错误会撕裂槽或让替换偷走帧。</p><p>条件变量：需要等页从磁盘来时，在未持写 latch 的路径上等待 I/O 完成。持 latch 等 I/O 是经典死锁与延迟源。</p><p><span class="marginnote">为什么重要：持 latch 等磁盘 I/O 是经典事故——几十微秒的临界区被拉成几毫秒，所有想碰这页的线程全堵在门口，延迟雪崩。等 I/O 永远放在未持 latch 的路径上做。</span></p>',12)),(n(),A(B,null,{default:t(()=>[r(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GET%5B%22%E5%8F%96%E9%A1%B5%22%5D%20--%3E%20PIN%5B%22pin%20%E9%98%B2%E6%8D%A2%E5%87%BA%22%5D%0A%20%20PIN%20--%3E%20L%5B%22%E7%9F%AD%20latch%20%E4%BF%9D%E6%8A%A4%E9%A1%B5%E7%BB%93%E6%9E%84%22%5D%0A%20%20L%20--%3E%20USE%5B%22%E8%AF%BB%E6%A7%BD%20%2F%20%E6%94%B9%E6%A7%BD%22%5D%0A%20%20USE%20--%3E%20UL%5B%22%E6%94%BE%20latch%22%5D%0A%20%20UL%20--%3E%20UP%5B%22unpin%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"WAL：必须先日志后改页，且常在写 latch 下，避免半改页被读者看见。steal：未提交脏页可换出，但须已记日志；pin 不阻止已 unpin 的脏页成为牺牲者。",-1)),(n(),A(B,null,{default:t(()=>[r(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20LOCKT%5B%22lock%3A%20%E4%BA%8B%E5%8A%A1%E5%B1%82%22%5D%0A%20%20%20%20A1%5B%22%E4%BF%9D%E6%8A%A4%E8%A1%8C%E6%88%96%E8%A1%A8%E7%9A%84%E9%80%BB%E8%BE%91%E5%86%85%E5%AE%B9%22%5D%20--%3E%20A2%5B%22%E5%8F%AF%E8%B7%A8%E7%94%A8%E6%88%B7%E4%BA%A4%E4%BA%92%2C%20%E6%AD%BB%E9%94%81%E8%B5%B0%E6%A3%80%E6%B5%8B%22%5D%0A%20%20end%0A%20%20subgraph%20LAT%5B%22latch%3A%20%E9%A1%B5%E7%89%A9%E7%90%86%E5%B1%82%22%5D%0A%20%20%20%20B1%5B%22%E4%BF%9D%E6%8A%A4%E6%A7%BD%E6%95%B0%E7%BB%84%E9%A1%B5%E5%A4%B4%E4%B8%8D%E6%92%95%E8%A3%82%22%5D%20--%3E%20B2%5B%22%E5%BE%AE%E7%A7%92%E7%BA%A7%E4%B8%B4%E7%95%8C%E5%8C%BA%2C%20%E5%9B%BA%E5%AE%9A%E9%A1%BA%E5%BA%8F%E9%98%B2%E6%AD%BB%E9%94%81%22%5D%0A%20%20end%0A%20%20subgraph%20PINN%5B%22pin%3A%20%E5%B8%A7%E5%AF%BF%E5%91%BD%E5%B1%82%22%5D%0A%20%20%20%20C1%5B%22%E7%A6%81%E6%AD%A2%E7%BC%93%E5%86%B2%E6%B1%A0%E6%8D%A2%E5%87%BA%E8%AF%A5%E5%B8%A7%22%5D%20--%3E%20C2%5B%22%E8%AE%A1%E6%95%B0%E5%BD%92%E9%9B%B6%E5%90%8E%E5%B8%A7%E6%89%8D%E5%8F%AF%E8%A2%AB%E7%89%BA%E7%89%B2%22%5D%0A%20%20end%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p>监控：pin 泄漏（忘记 unpin）会让池中帧永远钉死，表现为池缩小。这是实现 bug，不是策略。</p><p><span class="marginnote">数字实例：8 GB 池、16 KB 页共约 52 万帧；若 100 帧被忘记 unpin，池就凭空少了 100 页容量且永不归还——外在表现常常只是命中率悄悄下滑，很难第一眼定位。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 B+ 遍历时的 latch 耦合（crabbing）。也不把 pthread mutex 当事务锁教。意向锁是事务粒度，后课。</p><p>后课默认：碰页先 pin，改结构持 latch，事务语义用 lock/MVCC。latch crabbing：遍历索引时如何避免同时钉整条根到叶。</p><p>Latch 不是隔离级别。它只让页在物理上可读可写而不撕裂。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>pin 管帧寿命；latch 管页内短互斥；lock 管事务。</li><li>持 latch 不做 I/O；unpin 泄漏会饿死缓冲池。</li><li>latch crabbing 下一课：索引遍历的闩锁耦合。</li><li>出处：Gray and Reuter；Mohan ARIES；Ramakrishnan and Gehrke。</li></ul>',8))])}const g=p(o,[["render",h]]);export{f as __pageData,g as default};
